-- Anonymous usage statistics.
--
-- Only two things are stored: a random install ID generated by the extension
-- and, per UTC day, how many items it hid. The tables live in a private schema
-- that the Data API does not expose, and the only way in is record_usage(),
-- which can be executed by the service role alone (used by the `track` Edge
-- Function).

create schema if not exists usage_stats;
revoke all on schema usage_stats from public, anon, authenticated;

create table usage_stats.installs (
  id uuid primary key,
  first_seen date not null default (now() at time zone 'utc')::date,
  last_seen date not null default (now() at time zone 'utc')::date
);

create table usage_stats.daily_usage (
  install_id uuid not null references usage_stats.installs (id) on delete cascade,
  day date not null,
  hidden_count integer not null default 0 check (hidden_count between 0 and 20000),
  primary key (install_id, day)
);

alter table usage_stats.installs enable row level security;
alter table usage_stats.daily_usage enable row level security;
revoke all on all tables in schema usage_stats from public, anon, authenticated;

create or replace function public.record_usage(p_install_id uuid, p_day date, p_hidden integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'utc')::date;
begin
  if p_install_id is null or p_day is null or p_hidden is null then
    raise exception 'missing field' using errcode = '22023';
  end if;
  if p_day < today - 2 or p_day > today then
    raise exception 'day out of range' using errcode = '22023';
  end if;
  if p_hidden < 0 or p_hidden > 20000 then
    raise exception 'hidden out of range' using errcode = '22023';
  end if;

  insert into usage_stats.installs as i (id)
  values (p_install_id)
  on conflict (id) do update set last_seen = greatest(i.last_seen, excluded.last_seen);

  insert into usage_stats.daily_usage as d (install_id, day, hidden_count)
  values (p_install_id, p_day, p_hidden)
  on conflict (install_id, day) do update set hidden_count = greatest(d.hidden_count, excluded.hidden_count);
end;
$$;

revoke all on function public.record_usage(uuid, date, integer) from public, anon, authenticated;
grant execute on function public.record_usage(uuid, date, integer) to service_role;

-- Totals for dashboards: select * from public.usage_summary();
create or replace function public.usage_summary()
returns table (total_users bigint, active_users_30d bigint, total_hidden bigint)
language sql
stable
security definer
set search_path = ''
as $$
  select
    (select count(*) from usage_stats.installs),
    (select count(*) from usage_stats.installs
      where last_seen >= (now() at time zone 'utc')::date - 30),
    (select coalesce(sum(hidden_count), 0) from usage_stats.daily_usage);
$$;

revoke all on function public.usage_summary() from public, anon, authenticated;
grant execute on function public.usage_summary() to service_role;
